  async function resendVerification(){try{const j=await authPost({action:'resend_verification'});say(j.message||'Verification email queued.')}catch(e){say(e.message)}}
  async function manageBilling(){try{const j=await secureJsonPost('subscription.php',{action:'portal'});if(j.portal_url){location.href=j.portal_url;return}say('Billing portal unavailable.')}catch(e){say(e.message)}}
  async function cancelSubscription(){if(!confirm('Cancel this subscription at the end of the current billing period?'))return;try{await secureJsonPost('subscription.php',{action:'cancel'});say('Cancellation scheduled.',()=>renderAccount())}catch(e){say(e.message)}}
  async function resumeSubscription(){try{await secureJsonPost('subscription.php',{action:'resume'});say('Subscription resumed.',()=>renderAccount())}catch(e){say(e.message)}}
  async function revokeOtherSessions(){if(!confirm('Sign out every other persistent Stonefellow session?'))return;try{const j=await authPost({action:'revoke_other_sessions'});say(`${Number(j.revoked||0)} other session${Number(j.revoked||0)===1?'':'s'} signed out.`,()=>renderAccount())}catch(e){say(e.message)}}
  async function revokeSession(id){try{await authPost({action:'revoke_session',session_id:id});say('Session signed out.',()=>renderAccount())}catch(e){say(e.message)}}
  async function renderOrderDetail(id){try{const r=await fetch((cfg.apiBase||'api')+'/customer-order.php?id='+encodeURIComponent(id),{cache:'no-store',credentials:'same-origin'}),j=await r.json();if(!r.ok||j.ok===false)throw new Error(j.message||'Order not found.');const o=j.order||{},q=o.quote||{},payment=o.payment||{},pod=o.pod||[],timeline=o.timeline||[],ship=o.customer?.shipping||null,f=o.fulfillment||{},fStatus=f.status||(!q.physical?'not_required':'pending');canvas.innerHTML=`<article class="module auth-module"><div class="module-kicker">ORDER DETAILS</div><h2>${esc(o.id||id)}</h2><div class="token-panel"><div class="token-stat"><strong>${esc(o.status||'')}</strong><span>Order status</span></div><div class="token-stat"><strong>${new Intl.NumberFormat('en-US',{style:'currency',currency:q.currency||'USD'}).format((q.total_cents||0)/100)}</strong><span>Total</span></div><div class="token-stat"><strong>${esc(payment.status||'—')}</strong><span>Payment</span></div><div class="token-stat"><strong>${esc(fStatus)}</strong><span>Fulfillment</span></div></div><div class="account-orders"><div class="module-kicker">ITEMS</div>${(q.items||[]).map(i=>`<div class="account-order"><div><strong>${esc(i.label||i.type)}</strong><small>${esc(i.type||'item')}</small></div><strong>${new Intl.NumberFormat('en-US',{style:'currency',currency:q.currency||'USD'}).format((i.price_cents||0)/100)}</strong></div>`).join('')}</div>${ship?`<div class="account-orders"><div class="module-kicker">SHIPPING</div><p class="player-note">${esc(ship.line1||'')}${ship.line2?'<br>'+esc(ship.line2):''}<br>${esc(ship.city||'')}, ${esc(ship.region||'')} ${esc(ship.postal||'')}<br>${esc(ship.country||'')}</p></div>`:''}<div class="account-orders"><div class="module-kicker">FULFILLMENT</div>${q.physical?`<div class="account-order"><div><strong>${esc(fStatus.replaceAll('_',' '))}</strong><small>${esc(f.updated_at?('Updated '+String(f.updated_at).replace('T',' ').slice(0,19)):'')}</small></div>${f.tracking_number?`<div><strong>${esc(f.carrier||'Tracking')}</strong><small>${esc(f.tracking_number)}</small>${f.tracking_url?`<a class="text-control inline-link" href="${esc(f.tracking_url)}" target="_blank" rel="noopener">Track shipment</a>`:''}</div>`:''}</div>${f.note?`<p class="player-note">${esc(f.note)}</p>`:''}${pod.length?pod.map(x=>`<div class="account-order"><div><strong>${esc(x.status||'POD')}</strong><small>${esc(x.file||'')}</small></div></div>`).join(''):''}`:'<p class="player-note">No physical fulfillment is required for this order.</p>'}</div>${timeline.length?`<div class="account-orders"><div class="module-kicker">ORDER TIMELINE</div>${timeline.slice().reverse().map(x=>`<div class="account-order"><div><strong>${esc(x.label||x.status||x.type)}</strong><small>${esc((x.created_at||'').replace('T',' ').slice(0,19))}</small></div></div>`).join('')}</div>`:''}<div class="player-controls"><button class="text-control" type="button" data-view="account">Back to account</button></div></article>`;bind(canvas)}catch(e){say(e.message,()=>navigate('account'))}}
  async function saveCurrentBuildToAccount(){
    try{const j=await secureJsonPost('builds.php',{action:'save',build:st.builder});say('Your current '+st.builder.format+' build is saved to your account.',()=>renderAccount())}catch(e){say(e.message)}
  }
  function loadAccountBuild(id,rows){const row=(rows||[]).find(x=>Number(x.id)===Number(id));if(!row||!row.build)return;st.builder={...defaultBuild(),...row.build,version:3};persist();say('Loaded “'+(row.name||st.builder.title)+'.”',()=>navigate('builder'))}
  async function deleteAccountBuild(id){if(!confirm('Delete this saved build?'))return;try{await secureJsonPost('builds.php',{action:'delete',id});say('Saved build deleted.',()=>renderAccount())}catch(e){say(e.message)}}
  function renderProfileForm(){
    const u=st.auth.user;if(!u){renderLogin();return}
    canvas.innerHTML=`<article class="module auth-module"><div class="module-kicker">ACCOUNT SETTINGS</div><h2>Your profile</h2><form id="profileForm" class="auth-form"><label>Display name<input name="display_name" value="${esc(u.display_name)}" required maxlength="100"></label><p id="authError" class="auth-error"></p><div class="auth-actions"><button class="buy-primary" type="submit">Save</button><button class="text-control" type="button" data-view="account">Cancel</button></div></form><form id="emailForm" class="auth-form"><h3>Change email</h3><label>New email<input name="email" type="email" autocomplete="email" required value="${esc(u.email)}"></label><label>Current password<input name="current_password" type="password" autocomplete="current-password" required></label><p id="emailError" class="auth-error"></p><button class="text-control" type="submit">Change email + verify</button></form><form id="accountPasswordForm" class="auth-form"><h3>Change password</h3><label>Current password<input name="current" type="password" autocomplete="current-password" required></label><label>New password<input name="next" type="password" minlength="10" autocomplete="new-password" required></label><label>Confirm new password<input name="confirm" type="password" minlength="10" autocomplete="new-password" required></label><p id="passwordError" class="auth-error"></p><button class="text-control" type="submit">Change password</button></form></article>`;
    bind(canvas);$('#profileForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),er=$('#authError');er.textContent='';try{await authPost({action:'profile',display_name:f.get('display_name')});location.href='?view=account'}catch(x){er.textContent=x.message}};$('#emailForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),er=$('#emailError');er.textContent='';try{const j=await authPost({action:'change_email',email:f.get('email'),current_password:f.get('current_password')});if(j.user){st.auth.user=j.user}er.textContent=j.message||'Email updated.';setTimeout(()=>navigate('account'),700)}catch(x){er.textContent=x.message}};$('#accountPasswordForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),er=$('#passwordError');er.textContent='';try{const j=await authPost({action:'password',current_password:f.get('current'),new_password:f.get('next'),confirm:f.get('confirm')});if(j.csrf)st.auth.csrf=j.csrf;e.currentTarget.reset();er.textContent='Password updated.'}catch(x){er.textContent=x.message}};
  }
  async function liveAgent(text){await loadAuth();if(!st.auth.authenticated){say('Create a free account to use the live Stonefellow AI agent. Your music player will keep playing.',()=>navigate('register'));return}agent('thinking','Thinking…');try{const u=new URL(location.href),view=u.searchParams.get('view')||'home',client_state={view,active_track_id:st.track?.id||'',builder_format:st.builder.format,builder_side_a_count:st.builder.A.length,builder_side_b_count:st.builder.B.length,playlist_id:st.playlistPlayback.playlistId||null,playlist_name:st.playlistPlayback.playlistName||'',agent_listening_session_id:agentSessionVisible()?st.agentSession.id:'',queue_count:st.queue.items.length};const j=await secureJsonPost('agent-chat.php',{message:text,conversation_id:st.conversationId,client_state});st.conversationId=j.conversation_id||st.conversationId;if(st.conversationId)localStorage.setItem('stonefellow.agent.conversation',st.conversationId);await executeAgentAction(j.action);say(j.text||'Ready.')}catch(e){if(e.payload?.error==='active_tokens_required'){say(e.message||'You are out of Active Tokens.',()=>navigate('plans'));return}say('The live agent is unavailable right now. '+e.message)}}
  async function renderPlans(){await Promise.all([loadPlans(),loadAuth(),loadStore()]);starters.hidden=true;canvas.innerHTML=`<article class="module"><div class="module-kicker">STONEFELLOW MEMBERSHIP</div><h2>Plans</h2><p class="player-note">Active Tokens power live AI conversation and optional ElevenLabs voice. Paid production plans use secure hosted billing when configured.</p><div class="plan-grid">${st.plans.map(p=>`<section class="plan-card ${p.is_featured?'featured':''}"><div class="module-kicker">${p.trial_days?`${p.trial_days}-DAY FREE TRIAL`:'MONTHLY'}</div><h3>${esc(p.name)}</h3><div class="plan-price">${p.monthly_price_cents?money(p.monthly_price_cents):'Free'}${p.monthly_price_cents?'<small> / month</small>':''}</div><p class="player-note">${esc(p.description||'')}</p><div class="plan-features">${(p.features||[]).map(x=>`<span>• ${esc(x)}</span>`).join('')}<span>• ${Number(p.monthly_tokens||0).toLocaleString()} monthly Active Tokens</span>${p.trial_tokens?`<span>• ${Number(p.trial_tokens).toLocaleString()} trial tokens</span>`:''}</div><button class="buy-primary" type="button" data-choose-plan="${p.id}">${st.auth.authenticated?'Choose plan':'Start free trial'}</button></section>`).join('')||'<p class="player-note">No public packages are available yet.</p>'}</div></article>`;$$('[data-choose-plan]',canvas).forEach(b=>b.onclick=()=>{st.selectedPlanId=Number(b.dataset.choosePlan);st.auth.authenticated?activatePlan(st.selectedPlanId):navigate('register',{plan:st.selectedPlanId})})}
  async function activatePlan(id){const p=st.plans.find(x=>Number(x.id)===Number(id));if(!p)return;try{const j=await secureJsonPost('subscription.php',{action:'choose_package',package_id:id});if(j.checkout_url){location.href=j.checkout_url;return}if(j.portal_url){location.href=j.portal_url;return}say((j.simulated?'Test subscription activated. ':'')+p.name+' is now active.',()=>navigate('account'))}catch(e){say(e.message)}}
  async function loadStore(){if(st.store)return st.store;try{const health=await fetch((cfg.apiBase||'api')+'/health.php',{cache:'no-store'}).then(r=>r.json());st.store={mode:health.mode||'test',currency:'USD'};return st.store}catch(_){st.store={mode:'offline',currency:'USD'};return st.store}}
  async function refreshSiteData(){try{const r=await fetch((cfg.apiBase||'api')+'/site-data.php',{cache:'no-store'});const j=await r.json();if(r.ok&&j.ok){if(Array.isArray(j.catalog))catalog=j.catalog.map(x=>({...x,mood:x.mood||[],themes:x.themes||[],credits:x.credits||[]}));if(Array.isArray(j.releases))releases=j.releases;return true}}catch(_){}return false}
  function setUrl(view,params={}){const u=new URL(location.href);u.search='';if(view&&view!=='home')u.searchParams.set('view',view);Object.entries(params).forEach(([k,v])=>{if(v!==undefined&&v!==null&&v!=='')u.searchParams.set(k,v)});history.pushState({view,params},'',u)}
  function closeMenu(){if(menu?.tagName==='DETAILS'){menu.open=false}else{menu?.classList.remove('open');menu?.setAttribute('aria-hidden','true')}$('#menuButton')?.setAttribute('aria-expanded','false')}
  function recommendationCard(x){const t=trackById(x.track_id)||x,reasons=Array.isArray(x.reasons)?x.reasons:[];return `<article class="recommendation-card"><button class="recommendation-play" type="button" data-recommend-play="${esc(x.track_id)}" aria-label="Play ${esc(x.title||t.title||'recommendation')}">▶</button><button class="recommendation-main" type="button" data-recommend-open="${esc(x.track_id)}"><span class="recommendation-art">${(x.artwork||t.artwork)?`<img src="${esc(x.artwork||t.artwork)}" alt="">`:'SF'}</span><span><strong>${esc(x.title||t.title||x.track_id)}</strong><small>${esc(x.release||t.release||'Stonefellow')}</small>${reasons.length?`<em>${esc(reasons[0])}</em>`:''}</span></button>${favoriteButton('track',x.track_id,'Favorite')}</article>`}
